function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100) return 'nums needs 1 to 100 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -100 || v > 100)) return 'Each value is an integer between -100 and 100.';
  return null;
}

