function frequencySort(nums) {
  const count = new Map();
  for (const num of nums) {
    count.set(num, (count.get(num) || 0) + 1);
  }

  nums.sort((a, b) => {
    const diff = count.get(a) - count.get(b);
    if (diff !== 0) {
      return diff;
    }
    return b - a;
  });
  return nums;
}

