function frequencySort(nums) {
  // Repeatedly take the least frequent remaining value (the larger one on ties) and emit all its copies.
  const occurrences = value => nums.filter(x => x === value).length;
  const remaining = [...new Set(nums)];
  const result = [];
  while (remaining.length) {
    let pick = 0;
    for (let i = 1; i < remaining.length; i++) {
      const fi = occurrences(remaining[i]), fp = occurrences(remaining[pick]);
      if (fi < fp || (fi === fp && remaining[i] > remaining[pick])) pick = i;
    }
    const value = remaining.splice(pick, 1)[0];
    for (let k = occurrences(value); k > 0; k--) result.push(value);
  }
  return result;
}

