function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 100 : 1 + Math.floor(rand() * 12);
  // A narrow range gives many repeats and frequency ties; the full range gives mostly distinct values.
  const mode = rand();
  const span = mode < 0.4 ? 3 + Math.floor(rand() * 8) : mode < 0.7 ? 30 : 100;
  const center = Math.floor(rand() * (2 * (100 - span) + 1)) - (100 - span);
  const nums = Array.from({ length: n }, () => center + Math.floor(rand() * (2 * span + 1)) - span);
  return [nums];
}
